import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    moves = [int(data[idx + i]) for i in range(k)]

    win = [False] * (n + 1)
    for i in range(1, n + 1):
        for s in moves:
            if s <= i and not win[i - s]:
                win[i] = True
                break

    if win[n]:
        for s in sorted(moves):
            if s <= n and not win[n - s]:
                print(f"WIN {s}")
                return
    else:
        print("LOSE")

main()
